mapper.sql:
FROM ph_inv_expiry_alert a
JOIN ph_inv_batch b ON b.id = a.batch_id AND b.tenant_id = a.tenant_id
JOIN ph_warehouse w ON w.id = b.warehouse_id AND w.tenant_id = b.tenant_id
                   AND w.store_id = b.store_id
WHERE a.tenant_id = #{scope.tenantId} AND a.store_id = #{scope.storeId}
  AND b.tenant_id = #{scope.tenantId} AND b.store_id = #{scope.storeId}
  AND w.tenant_id = #{scope.tenantId} AND w.store_id = #{scope.storeId}
  AND a.deleted = b'0' AND b.deleted = b'0' AND w.deleted = b'0'
AND b.warehouse_id = #{q.warehouseId}
AND a.drug_id = #{q.drugId}
AND a.batch_id = #{q.batchId}
AND a.alert_level = #{q.alertLevel}
AND a.handle_type = #{q.handleType}
AND a.alert_date = #{q.alertDate}

mapper.select:
SELECT handle_type FROM ph_inv_expiry_alert
WHERE id = #{id} AND tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId}
  AND deleted = b'0'
